import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Compress values to 0..k-1.
        long[] keys = a.clone();
        Arrays.sort(keys);
        int k = 0;
        for (int i = 0; i < n; i++)
            if (i == 0 || keys[i] != keys[i - 1]) keys[k++] = keys[i];
        int[] id = new int[n], last = new int[k], counts = new int[k];
        for (int i = 0; i < n; i++) {
            id[i] = Arrays.binarySearch(keys, 0, k, a[i]);
            last[id[i]] = i;
        }
        // Cut the array into minimal closed blocks; each block keeps its most frequent value.
        long answer = 0;
        int end = 0, start = 0, largest = 0;
        for (int i = 0; i < n; i++) {
            end = Math.max(end, last[id[i]]);
            largest = Math.max(largest, ++counts[id[i]]);
            if (i == end) {
                answer += i - start + 1 - largest;
                start = i + 1;
                largest = 0;
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	last := make(map[int]int, n)
	for i, v := range a {
		last[v] = i
	}
	counts := make(map[int]int, n)
	// Cut the array into minimal closed blocks; each block keeps its most frequent value.
	answer, end, start, largest := 0, 0, 0, 0
	for i, v := range a {
		end = max(end, last[v])
		counts[v]++
		largest = max(largest, counts[v])
		if i == end {
			answer += i - start + 1 - largest
			start = i + 1
			largest = 0
		}
	}
	fmt.Println(answer)
}
